package com.antra.analytics; import java.util.concurrent.atomic.LongAdder; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.kafka.annotation.*; import org.springframework.stereotype.*;
@SpringBootApplication public class AnalyticsApplication {public static void main(String[] a){SpringApplication.run(AnalyticsApplication.class,a);}@Component static class Listener {private final LongAdder reservations=new LongAdder();@KafkaListener(topics="reservation-created",groupId="analytics") void onReservation(Object e){reservations.increment();System.out.println("Reservations observed="+reservations.sum());}}}
